<script setup lang="ts">
import { ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import { authApi } from '@/features/auth/api/auth.api'
import { sessionStore } from '@/store/session'
const loginName=ref(''),password=ref(''),showPassword=ref(false),loading=ref(false),error=ref('')
async function login(){if(!loginName.value.trim()||!password.value)return error.value='请输入账号和密码';loading.value=true;error.value='';try{const session=await authApi.login(loginName.value,password.value);sessionStore.applyAuthenticatedSession(session);uni.reLaunch({url:'/workbenches/home/index'})}catch(e){error.value=e instanceof Error?e.message:'登录失败，请稍后重试'}finally{loading.value=false}}
onLoad(()=>{if(sessionStore.restore())uni.reLaunch({url:'/workbenches/home/index'})})
</script>
<template><view class="page"><view class="brand"><view class="mark"><view/><view/><view/></view><text class="name">梦花仓管</text><text class="slogan">鲜切花仓库作业协同工具</text></view><view class="panel"><text class="welcome">欢迎登录</text><text class="tip">使用分配给你的仓管账号</text><view class="field"><text>账号</text><input v-model="loginName" placeholder="账号或手机号"/></view><view class="field"><text>密码</text><input v-model="password" :password="!showPassword" placeholder="请输入密码" confirm-type="done" @confirm="login"/><text class="toggle" @click="showPassword=!showPassword">{{showPassword?'隐藏':'显示'}}</text></view><text v-if="error" class="error">{{error}}</text><button :loading="loading" :disabled="loading" @click="login">{{loading?'正在登录':'登录'}}</button><text class="support">账号由管理员统一创建，一个账户对应一个角色</text></view><view class="footer">梦花仓管 · 昆明斗南鲜切花仓</view></view></template>
<style scoped lang="scss">.page{box-sizing:border-box;min-height:100vh;padding:150rpx 40rpx 50rpx;background:linear-gradient(165deg,#e0f2ed 0,#f3f7f6 42%,#f3f7f6 100%)}.brand{text-align:center}.mark{position:relative;width:84rpx;height:84rpx;margin:0 auto 22rpx;border-radius:26rpx;background:var(--wms-primary-700);transform:rotate(45deg)}.mark view{position:absolute;width:24rpx;height:36rpx;border-radius:50% 50% 45% 45%;background:#fff}.mark view:nth-child(1){top:14rpx;left:14rpx}.mark view:nth-child(2){top:14rpx;right:14rpx;transform:rotate(90deg)}.mark view:nth-child(3){right:14rpx;bottom:14rpx}.name,.slogan{display:block}.name{color:var(--wms-text);font-size:46rpx;font-weight:850;letter-spacing:4rpx}.slogan{margin-top:12rpx;color:var(--wms-text-secondary);font-size:22rpx}.panel{margin-top:70rpx;padding:36rpx 30rpx;border-radius:28rpx;background:#fff;box-shadow:0 18rpx 60rpx rgba(15,70,65,.09)}.welcome,.tip{display:block}.welcome{font-size:34rpx;font-weight:800}.tip{margin-top:8rpx;color:var(--wms-text-secondary);font-size:21rpx}.field{position:relative;margin-top:28rpx}.field>text:first-child{display:block;margin-bottom:10rpx;font-size:22rpx;font-weight:650}.field input{box-sizing:border-box;width:100%;height:84rpx;padding:0 22rpx;border-radius:16rpx;background:var(--wms-page);font-size:25rpx}.field .toggle{position:absolute;right:20rpx;bottom:27rpx;color:var(--wms-primary-700);font-size:20rpx}.error{display:block;margin-top:16rpx;color:var(--wms-danger);font-size:20rpx}.panel button{height:86rpx;margin-top:30rpx;border:0;border-radius:17rpx;background:var(--wms-primary-700);color:#fff;font-size:27rpx;font-weight:750;line-height:86rpx}.panel button[disabled]{opacity:.6}.support{display:block;margin-top:20rpx;color:var(--wms-text-secondary);font-size:19rpx;text-align:center}.footer{position:fixed;right:0;bottom:34rpx;left:0;color:var(--wms-text-secondary);font-size:18rpx;text-align:center}</style>
